from lib import *
chapter(7,'maths','another-peek-beyond-the-point','Another Peek Beyond the Point',
 ('At the shop','Meena buys 2.5 kg of rice at Rs 48.50 a kilogram. How much does she pay? Money and measures use decimals, and we must add, subtract, multiply and divide them correctly.'),
 [('Adding and subtracting decimals',['Line up the decimal points so tenths are under tenths and hundredths under hundredths.','Add or subtract as with whole numbers and keep the point in the same place in the answer.','Money works this way: Rs 12.50 plus Rs 7.75 is Rs 20.25.']),
  ('Multiplying decimals',['Multiply as if there were no decimal points. Then count the total digits after the points in both numbers and place the point that many places from the right.','2.5 times 4 is 10.0 which is 10. 0.3 times 0.2 is 0.06.']),
  ('Dividing decimals',['To divide by a decimal, multiply both numbers by 10 or 100 to make the divisor whole.','6.4 divided by 0.8 is the same as 64 divided by 8, which is 8.']),
  ('Estimating first',['Look before you leap: estimate the answer first by rounding. 4.9 times 2.1 is about 5 times 2, which is 10, so an answer like 1.029 or 102.9 must be wrong.'])],
 [('Find 2.5 x 48.5.',[('Estimate: 2.5 times 50 is about 125.','Rough value.'),('25 times 485 is 12,125; two decimal places gives 121.25.','Place the point.')])],
 ('Why do we line up decimal points when adding?',['Digits of the same place value must be added together.'],['Writing the answer with the point misplaced.']),
 ['Line up points to add or subtract.','Count decimal places to place the point when multiplying.','Make the divisor whole when dividing.','Estimate first.'],
 [num('1',1,'12.50 + 7.75 = ?',20.25,'Line up the points and add.',[(19.25,'Check the carrying of 0.50 plus 0.75.')]),
  num('2',1,'0.3 x 0.2 = ?',0.06,'3 times 2 is 6, two decimal places.',[(0.6,'There are two decimal places in total.')]),
  num('3',1,'6.4 / 0.8 = ?',8,'Same as 64 divided by 8.',[(0.8,'Remove the points the same number of places in both.')]),
  tf('4',1,'2.5 x 4 = 10.',True,'25 times 4 is 100, one decimal place gives 10.0.'),
  mcq('5',2,'Which is a sensible estimate for 4.9 x 2.1?','10',[('1','Too small.'),('100','Too large.')],'About 5 times 2.'),
  num('6',2,'15.6 - 8.75 = ?',6.85,'Line up: 15.60 minus 8.75.',[(7.15,'Check the borrowing.')]),
  num('7',2,'1.2 x 3 = ?',3.6,'12 times 3 is 36, one decimal place.',[(36,'Count the decimal place.')]),
  num('8',3,'Rs 48.50 per kg for 2 kg of rice costs Rs',97,'48.50 times 2.',[(9.7,'Place value is wrong.')],'Rs')],
 keep=['decimal','estimate'])
chapter(7,'maths','connecting-the-dots','Connecting the Dots',
 ('Marks in a test','Five friends scored 6, 7, 7, 8 and 12 out of 20. What is a fair single number to describe the group? That depends on how we choose it. This chapter is about data and summaries.'),
 [('Mean, median and mode',['The mean (or average) is the sum of all values divided by how many there are. For 6, 7, 7, 8, 12 the sum is 40 and the mean is 8.','The median is the middle value when the numbers are arranged in order. Here it is 7.','The mode is the value that occurs most often. Here it is 7.','The median is not changed much by one very large or small value, but the mean is.']),
  ('Bar graphs and pie charts',['A bar graph compares categories using bars. A pie chart shows parts of a whole as slices of a circle.','Each slice of a pie chart is a fraction of the whole.']),
  ('Line graphs',['A line graph shows how something changes over time, like temperature through the day.','Plot points with time on the horizontal axis and join them.']),
  ('Data and statements',['Data can be used to tell true stories, but be careful: a graph with a cut scale can mislead.','Always ask who collected the data and how.'])],
 [('Find the mean, median and mode of 6, 7, 7, 8, 12.',[('Mean is 40 divided by 5, which is 8.','Sum over count.'),('The middle value is 7, and 7 appears twice.','Median and mode.')])],
 ('Which would you use to describe a typical salary in a company with one very rich owner: mean or median?',['The median is not pulled by the rich owner.'],['Thinking the mean is always the best.']),
 ['Mean = sum / count.','Median is the middle value in order.','Mode is the most frequent value.','Choose graphs to fit the data.'],
 [num('1',1,'Mean of 6, 7, 7, 8, 12',8,'40 divided by 5.',[(7,'That is the median.')]),
  num('2',1,'Median of 6, 7, 7, 8, 12',7,'The middle number in order.',[(8,'That is the mean.')]),
  num('3',1,'Mode of 2, 3, 3, 5, 3, 9',3,'3 occurs three times.',[(5,'5 occurs once.')]),
  mcq('4',1,'A graph showing change over time is a','line graph',[('pie chart','It shows parts of a whole.'),('tally chart','It counts items.')],'Time on the horizontal axis.'),
  num('5',2,'Mean of 4, 6, 8',6,'18 divided by 3.',[(8,'The largest value is not the mean.')]),
  mcq('6',2,'Median of 3, 9, 5','5',[('9','Sort first: 3, 5, 9.'),('3','That is the smallest.')],'Middle after arranging.'),
  tf('7',2,'A pie chart shows parts of a whole.',True,'Each slice is a share of the whole circle.'),
  mcq('8',3,'One very large value changes the','mean most',[('mode most','Mode ignores size.'),('median most','Median stays in the middle.')],'The mean uses all values.')],
 keep=['mean','median','mode'])
chapter(7,'maths','constructions-and-tilings','Constructions and Tilings',
 ('Floor tiles','A floor is covered with tiles without gaps. Why do square and hexagon tiles work but not pentagons? We construct shapes and explore tilings.'),
 [('Constructing angles',['With a compass we can construct 60 degrees by drawing arcs of the same radius. Bisecting 60 gives 30. Bisecting 90 gives 45.','To bisect an angle, draw arcs from both arms and join the vertex to where the arcs cross.']),
  ('Constructing triangles',['Given three sides, draw one side, then draw arcs from its two ends with the other two lengths. Join to the point where the arcs cross.','Given two angles and a side, or two sides and the included angle, we can also construct a triangle.']),
  ('Tessellations',['A tiling or tessellation covers a flat surface with shapes with no gaps and no overlaps.','Regular polygons that tile alone are equilateral triangles, squares and regular hexagons.','At every meeting point the angles must add up to 360 degrees. Hexagon angles are 120, and three of them make 360.'])],
 [('Why do squares tile a floor?',[('Each corner is 90 degrees.','Angle of a square.'),('Four corners make 360 degrees at a meeting point, so no gap.','Angle sum.')])],
 ('Explain why regular pentagons cannot tile a floor.',['A pentagon\'s angle is 108.','360 is not a multiple of 108.'],['Thinking any shape tiles.']),
 ['Compass arcs construct 60 and 30 degree angles.','Angles at a point add to 360.','Triangles, squares, hexagons tile.'],
 [mcq('1',1,'Which regular shape cannot tile a floor on its own?','Pentagon',[('Square','Square angles are 90, four make 360.'),('Hexagon','Hexagon angles are 120, three make 360.')],'108 does not divide 360.'),
  num('2',1,'How many 90 degree corners meet at a point in a square tiling?',4,'4 times 90 is 360.',[(3,'Three make 270, leaving a gap.')]),
  tf('3',1,'Regular hexagons can tile a floor.',True,'Three 120 degree angles fill 360.'),
  mcq('4',1,'Which tool constructs equal arcs?','Compass',[('Ruler','A ruler draws straight lines.'),('Protractor','It measures angles.')],'It keeps a fixed radius.'),
  num('5',2,'Angle of an equilateral triangle',60,'Six triangles make 360 at a point.',[(90,'That is a square.')],'degrees'),
  mcq('6',2,'Bisecting a 60 degree angle gives','30 degrees',[('120','That is double.'),('45','That is half of 90.')],'Half of 60.'),
  num('7',2,'How many equilateral triangles meet at a point in a tiling?',6,'6 times 60 is 360.',[(3,'Three make only 180.')]),
  mcq('8',3,'To construct a triangle with three sides you draw','one side and two arcs',[('three arcs only','You need a base first.'),('one arc only','Two arcs fix the third corner.')],'Arcs cross at the third vertex.')],
 keep=['tiling','bisect','compass'])
chapter(7,'maths','finding-the-unknown','Finding the Unknown',
 ('The balance','A balance has Rs 7 on the left and a bag plus Rs 2 on the right. If it is level, how much is in the bag? We find the unknown number using equations.'),
 [('Simple equations',['An equation says two expressions are equal, like x plus 2 equals 7. The letter stands for an unknown number.','Solving means finding the value of the letter that makes the equation true.']),
  ('Balancing',['An equation is like a level balance. Whatever we do to one side we must do to the other.','To solve x plus 2 equals 7, take 2 from both sides to get x equals 5.','To solve 3x equals 12, divide both sides by 3 to get x equals 4.','Always check by putting the answer back in the equation.']),
  ('Word problems',['Choose a letter for the unknown, write the situation as an equation and solve it.','A number plus 5 is 12: x plus 5 equals 12, so x is 7.']),
  ('Patterns and history',['Matchstick patterns can be written as equations. A row of n squares needs 3n plus 1 sticks.','Indian mathematicians such as Brahmagupta and Aryabhata wrote about solving equations long ago.'])],
 [('Solve 3x + 2 = 14.',[('Take 2 from both sides: 3x equals 12.','Balance.'),('Divide both sides by 3: x equals 4.','Check: 3 times 4 plus 2 is 14.')])],
 ('Explain why we do the same thing to both sides of an equation.',['The balance stays level.'],['Moving a number to the other side without changing its sign.']),
 ['An equation says two things are equal.','Do the same to both sides.','Check by substituting.','Form equations from word problems.'],
 [num('1',1,'Solve x + 2 = 7. x =',5,'Subtract 2 from both sides.',[(9,'You added instead of subtracting.')]),
  num('2',1,'Solve 3x = 12. x =',4,'Divide both sides by 3.',[(36,'You multiplied instead of dividing.')]),
  num('3',1,'Solve x - 4 = 6. x =',10,'Add 4 to both sides.',[(2,'Subtracting is wrong here.')]),
  tf('4',1,'We may add a number to one side only.',False,'The balance must be kept level.'),
  num('5',2,'Solve 3x + 2 = 14. x =',4,'3x is 12.',[(5,'Check by substitution: 3 times 5 plus 2 is 17.')]),
  mcq('6',2,'A number plus 5 is 12. The equation is','x + 5 = 12',[('5x = 12','This is 5 times x.'),('x - 5 = 12','This is 5 less.')],'Plus means add.'),
  num('7',2,'A pencil costs Rs 4. How many pencils cost Rs 28? n =',7,'4n equals 28.',[(24,'That subtracts instead of dividing.')]),
  num('8',3,'Matchsticks for 5 squares in a row using 3n + 1',16,'3 times 5 plus 1.',[(15,'Add the extra stick.')])],
 keep=['equation','balance'])
